/**
 * config.js — continuous task
 * Sequences loaded from task/sequences/continuous_sequences.json
 * (single master copy — generated by task/generate_sequences_momentmatch.py)
 * mean_range=10..90, std_fixed=15, values in [0,100]
 *
 * Common structure lives in shared/config-base.js — this file supplies only
 * what differs for the continuous task.
 */
import sequencesData from '../../sequences/continuous_sequences.json';
import { buildConfig, pickTutorialExample } from '../shared/config-base.js';

// Tutorial example is derived from a REAL main-task trial (closest true_mean
// to 50, subject to a visual-spread check on the first 5 values) rather than
// hand-picked literals -- see config-base.js's pickTutorialExample for why:
// hand-picked examples silently drift out of sync when sequences.json is
// regenerated with different mean_range/std_fixed, which already happened
// once (the tutorial's std=20 no longer matched the real std=15).
const { values: tutorialValues, mean: TUTORIAL_MEAN, std: TUTORIAL_STD } =
  pickTutorialExample(sequencesData, { isBinary: false, n: 5 });

export const config = buildConfig({
  taskType:      'continuous',
  sequencesData,
  tutorialValues,
  tutorialMean:  TUTORIAL_MEAN,
  tutorialStd:   TUTORIAL_STD,
  // No overrides — continuous currently uses all shared defaults.
});
